// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   panel a axis          → Cylinder r=0.022 (-3..3 on X) + 2 Cones        black
   panel a origin dot    → SphereGeometry(0.085)                          black
   panel a teal bar      → BoxGeometry(0.12, 0.7, 0.06)                   teal
   panel a pos. tint     → PlaneGeometry(1,0.9) scaled along X            teal 0.12
   panel b axes          → 2 × (Cylinder + 2 Cones)                       black
   panel b teal line     → BoxGeometry(5.6, 0.12, 0.03)                   teal
   panel b orange line   → BoxGeometry(5.6, 0.12, 0.03)                   terracotta
   panel b tint          → PlaneGeometry(6.6,3.3)                         sel. hue 0.12
   panel c gray plane    → PlaneGeometry(5,5) ⟂x3 + EdgesGeometry         #C6C9CA 0.8
   panel c teal plane    → PlaneGeometry(5,5) ⟂x1 + EdgesGeometry         #7FC8BF 0.75
   panel c orange plane  → PlaneGeometry(5,5) ⟂x2 + EdgesGeometry         #D2795C 0.8
   panel c axes          → solid Cylinders + Cones, hidden parts dashed   black
   panel c tint slab     → BoxGeometry(5,5,2.4)                           sel. hue 0.12
   origin dots           → SphereGeometry(0.085)                          black
   input point           → SphereGeometry(0.13) + dashed guide Lines      #34508F
   labels a) b) c) x1 x2 x3 → addLabel HTML (serif italic)                black
──────────────────────────────────────────────────────────────────────────── */

const CLR = {
  black: 0x000000, teal2: 0x8FD0C8, teal3: 0x7FC8BF,
  orange: 0xD2795C, gray: 0xC6C9CA, pt: 0x34508F
};
const HEX = { teal: '#5FB9AE', orange: '#D2795C', gray: '#9AA0A3' };

/* ── small builders ───────────────────────────────────────────────────── */
function thickLine(a, b, r, color) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 14),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function cone(tip, dirV, color, rad = 0.115, h = 0.34) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, h, 18),
    new THREE.MeshBasicMaterial({ color }));
  const dn = dirV.clone().normalize();
  m.position.copy(tip).addScaledVector(dn, -h * 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dn);
  return m;
}
function dashedSeg(a, b, color, ds = 0.15, gs = 0.12) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({ color, dashSize: ds, gapSize: gs }));
  l.computeLineDistances();
  return l;
}
function dynDashed(color) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(6), 3));
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({ color, dashSize: 0.13, gapSize: 0.1 }));
  l.setEnds = (a, b) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
    p.needsUpdate = true; g.computeBoundingSphere(); l.computeLineDistances();
  };
  l.setEnds(new THREE.Vector3(), new THREE.Vector3(0, 0, 0.001));
  return l;
}
function dot(r = 0.085) {
  return new THREE.Mesh(new THREE.SphereGeometry(r, 20, 14),
    new THREE.MeshBasicMaterial({ color: CLR.black }));
}
function axisDouble(dir, len) {
  const g = new THREE.Group();
  const a = dir.clone().multiplyScalar(-len), b = dir.clone().multiplyScalar(len);
  g.add(thickLine(a, b, 0.022, CLR.black));
  g.add(cone(b, dir, CLR.black));
  g.add(cone(a, dir.clone().negate(), CLR.black));
  return g;
}

/* ── objects excluded from camera auto-fit ────────────────────────────── */
const noFit = [];
function excludeFromFit(o) { o.__home = o.parent; noFit.push(o); return o; }

/* ── groups ───────────────────────────────────────────────────────────── */
const GA = new THREE.Group(), GB = new THREE.Group(), GC = new THREE.Group();

/* ---------- panel a) 1D ---------- */
GA.add(axisDouble(new THREE.Vector3(1, 0, 0), 3));
const aBand = new THREE.Mesh(new THREE.PlaneGeometry(1, 0.9),
  new THREE.MeshBasicMaterial({ color: CLR.teal2, transparent: true, opacity: 0.16, depthWrite: false }));
aBand.position.z = -0.05; GA.add(aBand); excludeFromFit(aBand);
const aBar = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.7, 0.06),
  new THREE.MeshBasicMaterial({ color: CLR.teal2 }));
aBar.userData.key = 'teal'; GA.add(aBar);
const aDot = dot(); aDot.position.z = 0.04; GA.add(aDot);
const aPoint = new THREE.Mesh(new THREE.SphereGeometry(0.13, 22, 16),
  new THREE.MeshBasicMaterial({ color: CLR.pt }));
GA.add(aPoint); excludeFromFit(aPoint);
const aGuide = dynDashed(CLR.pt); GA.add(aGuide); excludeFromFit(aGuide);

/* ---------- panel b) 2D ---------- */
GB.add(axisDouble(new THREE.Vector3(1, 0, 0), 3));
GB.add(axisDouble(new THREE.Vector3(0, 1, 0), 3));
const bTint = new THREE.Mesh(new THREE.PlaneGeometry(6.6, 3.3),
  new THREE.MeshBasicMaterial({ color: CLR.teal2, transparent: true, opacity: 0.16, depthWrite: false }));
GB.add(bTint); excludeFromFit(bTint);
function line2D(color, key) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(5.6, 0.12, 0.03),
    new THREE.MeshBasicMaterial({ color }));
  m.userData.key = key; GB.add(m); return m;
}
const bTeal = line2D(CLR.teal2, 'teal');
const bOrange = line2D(CLR.orange, 'orange');
bTeal.position.z = 0.02; bOrange.position.z = 0.01;
const bDot = dot(); bDot.position.z = 0.06; GB.add(bDot);
const bPoint = new THREE.Mesh(new THREE.SphereGeometry(0.13, 22, 16),
  new THREE.MeshBasicMaterial({ color: CLR.pt }));
bPoint.position.z = 0.08; GB.add(bPoint); excludeFromFit(bPoint);
const bGuides = { teal: dynDashed(CLR.pt), orange: dynDashed(CLR.pt) };
