  setRay(ev);
  const overPt = state.showPt && ray.intersectObject(currentPoint(), false).length > 0;
  const hits = overPt ? [] : ray.intersectObjects(pickList(), false);
  if (overPt) { canvas.style.cursor = 'move'; showTooltip('Drag this input point x', ev); }
  else if (hits.length) {
