/* ── state & hyperplane maths ─────────────────────────────────────────── */
const state = {
  dim: 1, w1: 1, b: 0, tint: true, showPt: true,
  sel: { 1: 'teal', 2: 'teal', 3: 'gray' },
  pt: {
    1: new THREE.Vector3(1.7, 0, 0),
    2: new THREE.Vector3(1.5, 1.2, 0),
