    const n = planeNormal(2, key), be = planeBias(2, key);
    const p0 = n.clone().multiplyScalar(-be);
    mesh.position.set(p0.x, p0.y, key === 'teal' ? 0.02 : 0.01);
    mesh.rotation.z = Math.atan2(n.x, -n.y);
    const foot = p.clone().addScaledVector(n, -(n.dot(p) + be));
    bGuides[key].visible = state.showPt;
    bGuides[key].setEnds(new THREE.Vector3(p.x, p.y, 0.05), new THREE.Vector3(foot.x, foot.y, 0.05));
