/* ── picking & dragging ───────────────────────────────────────────────── */
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitPt = new THREE.Vector3();
let dragging = false, movedPx = 0, downX = 0, downY = 0;

function setRay(ev) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  ray.setFromCamera(ndc, camera);
}
function currentPoint() { return state.dim === 1 ? aPoint : state.dim === 2 ? bPoint : cPoint; }
function pickList() {
  if (state.dim === 2) return [bTeal, bOrange];
  if (state.dim === 3) return [cPlanes.gray.mesh, cPlanes.teal.mesh, cPlanes.orange.mesh];
  return [aBar];
}

canvas.addEventListener('pointerdown', ev => {
  movedPx = 0; downX = ev.clientX; downY = ev.clientY;
  if (!state.showPt) return;
  setRay(ev);
  const hits = ray.intersectObject(currentPoint(), false);
  if (hits.length) {
    dragging = true; controls.enabled = false;
    if (state.dim === 3) {
      const nrm = new THREE.Vector3(); camera.getWorldDirection(nrm);
      dragPlane.setFromNormalAndCoplanarPoint(nrm, currentPoint().position.clone());
    } else {
      dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, 0));
    }
  }
});
canvas.addEventListener('pointermove', ev => {
  movedPx = Math.abs(ev.clientX - downX) + Math.abs(ev.clientY - downY);
  if (dragging) {
    setRay(ev);
    if (ray.ray.intersectPlane(dragPlane, hitPt)) {
      const p = state.pt[state.dim];
      if (state.dim === 1) p.set(THREE.MathUtils.clamp(hitPt.x, -2.9, 2.9), 0, 0);
      else if (state.dim === 2) p.set(THREE.MathUtils.clamp(hitPt.x, -2.9, 2.9), THREE.MathUtils.clamp(hitPt.y, -2.9, 2.9), 0);
      else p.set(THREE.MathUtils.clamp(hitPt.x, -2.6, 2.6), THREE.MathUtils.clamp(hitPt.y, -2.6, 2.6), THREE.MathUtils.clamp(hitPt.z, -2.6, 2.6));
      updateAll();
    }
    return;
  }
  // hover feedback
  setRay(ev);
  const overPt = state.showPt && ray.intersectObject(currentPoint(), false).length > 0;
  const hits = overPt ? [] : ray.intersectObjects(pickList(), false);
  if (overPt) { canvas.style.cursor = 'move'; showTooltip('Drag this input point x', ev); }
  else if (hits.length) {
    canvas.style.cursor = 'pointer';
    showTooltip('Click: select this neuron\'s hyperplane', ev);
  } else { canvas.style.cursor = state.dim === 3 ? 'grab' : 'default'; hideTooltip(); }
});
window.addEventListener('pointerup', ev => {
  if (dragging) { dragging = false; controls.enabled = true; return; }
  if (movedPx > 5) return;
  if (ev.target !== canvas) return;
  setRay(ev);
  const hits = ray.intersectObjects(pickList(), false);
  if (hits.length) {
    let o = hits[0].object;
    while (o && !o.userData.key) o = o.parent;
    if (o && o.userData.key) selectNeuron(o.userData.key, true);
  }
});

