let stepIdx = 0, tween = null, playTimer = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  if (s.dim !== state.dim) setDim(s.dim);
  tween = { t0: performance.now(), dur: 700, w0: state.w1, b0: state.b, w1: s.w, b1: s.b };
  narr.innerHTML = `<b>${stepIdx + 1}/${STEPS.length} · ${s.title}</b><br>${s.narration}`;
}
function tickTween() {
  requestAnimationFrame(tickTween);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k * k * (3 - 2 * k);
  state.w1 = tween.w0 + (tween.w1 - tween.w0) * e;
  state.b = tween.b0 + (tween.b1 - tween.b0) * e;
  syncSliders(); updateAll();
  if (k >= 1) tween = null;
}
tickTween();
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('playSteps').textContent = '▶ Play'; }
}
document.getElementById('prevStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('nextStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('playSteps').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playSteps').textContent = '❚❚ Pause';
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => {
    if (stepIdx === STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
  }, 4200);
});

